INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'Chemistry', 'Unit 5', 'Molarum Grade 10 — Chemistry METALS AND NONMETALS', 'Source-grounded Molarum Grade 10 Chemistry questions for METALS AND NONMETALS.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('cabae052-cf2a-4130-8c8c-cf730f256af3'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which of the following is a general property of metals?', 'Shiny and good conductor of electricity', 'Metals are typically lustrous and good conductors of heat and electricity.', 0),('2aec334c-9e31-4295-8c89-edf59bcfa463'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which property best distinguishes most nonmetals from metals?', 'Poor electrical conductivity', 'Nonmetals are generally poor conductors of electricity compared with metals.', 1),('bb2abfe0-b9aa-4c69-888d-bc0f27de5804'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'An alloy is', 'A mixture of two or more elements designed to improve properties', 'Alloys combine elements to enhance properties such as strength, hardness, or durability.', 2),('181394b9-4344-432d-83d2-67c3039cd4e2'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'true_false', 'Metals are generally malleable and ductile.', 'True', 'Metals are typically malleable and can be drawn into wires (ductile).', 3),('b59f87b8-5716-4005-8f5e-521ec36426b8'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which metal is commonly obtained from bauxite ore and used in the aircraft industry?', 'Aluminum', 'Aluminum is produced from bauxite ore and is lightweight, widely used in aircraft construction.', 4),('652a1cc6-7677-4e6b-8aa5-6e9ede8f6f6d'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Give one example of an alloy and its common use.', 'Steel — used in construction and for making tools.', 'Alloys improve properties such as strength and durability; steel (iron–carbon alloy) is widely used in construction and manufacturing.', 5),('ce16bbcd-a03d-4787-8d5c-bbf7b819b0ee'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'In a simplified reduction reaction, Fe2O3 yields 4 Fe. If 2.00 moles of Fe2O3 are reduced, how many grams of iron are produced? (Fe atomic mass = 55.85 g/mol)', '223.4 g', 'Stoichiometry:  Fe2O3 -> 4 Fe; moles Fe produced = 4.00 mol; mass Fe = 4.00 x 55.85 g/mol = 223.4 g.', 6),('2656850d-c18c-40c6-8fba-4ee118f6dd98'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which method is used to produce nitrogen gas on a large scale?', 'Fractional distillation of liquid air', 'Nitrogen gas is obtained industrially by fractional distillation of liquid air.', 7),('bd382634-a23b-476d-8605-2ee1892c934a'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Briefly outline two main stages in obtaining iron from its ore as described in 5.2.3.', '1) Extraction and concentration of iron ore; 2) Reduction in a blast furnace to produce iron, followed by refining to steel.', 'Iron production typically involves ore concentration, reduction to iron in a blast furnace, and subsequent refining.', 8),('070d7511-2b01-47d7-8339-e7547a1e878d'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'In brass, copper is 70% by mass and zinc 30%. A 1.20 kg sample of brass is melted. How many grams of copper and zinc are present?', 'Copper: 840 g; Zinc: 360 g', 'Masses are found by multiplying total mass by the mass percentages: Cu = 0.70 × 1200 g = 840 g; Zn = 0.30 × 1200 g = 360 g.', 9),('5672d179-5a4f-4513-8839-0031e97e73ec'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which of the following is a typical property of metals?', 'Malleable and good conductors of electricity', 'Metals are generally malleable and good conductors of heat and electricity, which distinguishes them from most nonmetals.', 10),('6e980777-9ae6-4592-8b1c-577a2bfa193d'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which statement about alloys is true?', 'Alloys are mixtures of two or more elements, at least one metal', 'Alloys are designed mixtures of elements, typically to improve properties such as strength; they are not limited to two metals and often change melting points.', 11),('5574dd0a-46a2-4e71-8a67-048c9e1964e0'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which process is primarily used to extract aluminum metal from its ore?', 'Electrolysis of molten alumina in cryolite', 'Industrial production of aluminum uses the Hall-Héroult process: electrolysis of alumina dissolved in cryolite to yield aluminum metal.', 12),('34b57483-52b9-4904-8d5d-53457f84df6d'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which nonmetal is most abundant in the Earth''s atmosphere and is commonly produced industrially by fractional distillation of liquid air?', 'Nitrogen', 'Nitrogen makes up about 78% of the atmosphere and is commonly produced industrially via fractional distillation of liquid air.', 13),('07eca42f-defb-491e-8210-87dee4ee512a'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Bronze is an alloy of copper and tin with improved hardness. Which statement is true?', 'It is an alloy of copper with tin.', 'Bronze is a copper-tin alloy; alloying generally alters properties like hardness and strength and still conducts electricity.', 14),('01198755-eb3f-4fff-8605-bd73f5344d21'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'true_false', 'All metals conduct electricity in the solid state.', 'True', 'Most metals have free electrons that allow electrical conduction in the solid state.', 15),('b254bd05-423a-44aa-8528-14046fe88638'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'State one general property of nonmetals and give one common use of a nonmetallic compound.', 'Nonmetals are poor conductors of electricity; ammonia (NH3) is commonly used as a fertilizer.', 'From 5.3.1, nonmetals are typically poor conductors; nonmetallic compounds like ammonia have agricultural uses.', 16),('a1ce7547-91a6-4fe9-83e7-ddf8f0d6465a'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Describe one industrial method for producing nitrogen gas.', 'Fractional distillation of liquid air.', 'Nitrogen is commonly produced industrially by fractional distillation of liquid air to separate N2 from O2 and other gases.', 17),('431f55e4-4095-48ea-8202-06a25fd65b6c'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'A bronze alloy contains 66 g copper and 34 g tin. What is the mass percentage of copper in the alloy?', '66%', 'Total mass = 66 g + 34 g = 100 g. Mass percentage of copper = (66/100) × 100 = 66%.', 18),('80dfabd0-8849-48d7-8b67-2bbe6e7b3a3f'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'An iron–carbon alloy contains 90 g iron and 10 g carbon. What is the mass percentage of iron in the alloy?', '90%', 'Mass percentage of iron = (90/100) × 100 = 90%.', 19),('432d531d-305b-4a92-8b4e-54d4feda2c1a'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which statement correctly contrasts metals with nonmetals?', 'Metals are generally good conductors of electricity and are malleable.', 'Metals typically conduct electricity well and are malleable, unlike most nonmetals which are poor conductors and brittle.', 20),('1f3b8708-f671-4a04-85fb-0fcb1a82525f'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which method is commonly used to obtain iron from its ore in a blast furnace?', 'Reduction with carbon (coke) in a blast furnace', 'Iron ore is reduced with coke (carbon) in a blast furnace to produce iron and slag.', 21),('697e35c5-3ad5-4c0b-8984-38f4c09cb096'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'An alloy is defined as', 'A substance made by melting two or more elements and combining them to improve properties', 'Alloys are combinations of elements designed to improve properties such as strength or durability.', 22),('4fecacc4-5003-48ed-8194-e2c65174f4c3'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which metal is primarily produced by the Hall-Héroult process?', 'Aluminum', 'The Hall-Héroult process is used to extract aluminum from its oxide.', 23),('b922e223-1d18-402c-8ddb-3b2e040d0ddb'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'In the blast furnace, limestone is added to form slag with impurities. What is the main purpose?', 'It forms slag with impurities to remove them from metal', 'Limestone decomposes to form lime which bonds with impurities to form slag, helping remove impurities from molten iron.', 24),('1f5238d0-86f7-407a-89d3-67b639646ce9'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'true_false', 'Nonmetals generally have high electrical conductivity.', 'False', 'Nonmetals are typically poor conductors of electricity.', 25),('f8dee46c-5b11-4cdf-87d7-747050f20b68'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Name two properties of metals that make them suitable for electrical wiring and give one example of a metal used for wiring.', 'Two properties: high electrical conductivity and ductility/malleability; Example: copper.', 'Metals used in wiring are chosen for good conductivity and ability to be drawn into wires (ductility). Copper is a common example.', 26),('5f0cc071-af3b-42f3-8511-68bb87eae7ba'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Describe two common uses of nonmetals or nonmetallic compounds.', 'Examples: nitrogen in fertilizers; chlorine in water disinfection; oxygen for respiration.', 'Nonmetals play key roles in agriculture (fertilizers) and public health (water disinfection) among other applications.', 27),('2b2d51e5-f867-4ac0-825d-59d7e9960e79'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'From 25.0 g Fe2O3, how many grams of iron (Fe) are produced in the reaction Fe2O3 + 3CO -> 2Fe + 3CO2? (Molar masses: Fe2O3 = 159.69 g/mol, Fe = 55.85 g/mol)', '17.5 g', 'Moles Fe2O3 = 25.0 g / 159.69 g/mol = 0.1566 mol. From the balanced equation, 2 mol Fe are produced per 1 mol Fe2O3, so Fe moles = 0.3132 mol; mass Fe = 0.3132 mol × 55.85 g/mol = 17.5 g.', 28),('47d5c201-bbb5-4783-887d-885625a764ca'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'From 60.0 g Cu2O (copper(I) oxide), how many grams of copper (Cu) are produced by the reaction 2Cu2O + C → 4Cu + CO? (Molar masses: Cu = 63.55 g/mol, Cu2O = 143.10 g/mol)', '53.3 g', 'Moles Cu2O = 60.0 g / 143.10 g/mol = 0.4193 mol. From the balanced equation, 4 mol Cu are produced per 2 mol Cu2O, i.e., 2 mol Cu per 2 mol Cu2O, so Cu moles = 0.4193 mol × 2 = 0.8386 mol. Mass Cu = 0.8386 mol × 63.55 g/mol = 53.3 g.', 29),('37afd143-734c-4faa-8884-17c1e8f625bd'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which of the following best describes metals?', 'They are malleable, ductile and good conductors of electricity.', 'Metals are typically malleable and ductile, and they conduct heat and electricity well due to metallic bonding with delocalized electrons.', 30),('b24837da-1fe4-414a-891c-df043448f85c'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Brass is an alloy of copper and zinc. Increasing the zinc content generally makes brass:', 'Increase hardness and decrease malleability.', 'Brass (Cu-Zn alloy) becomes harder and less malleable as zinc content increases due to changes in the crystal structure and bonding.', 31),('0cb65955-b6ff-4b12-84ef-e840c1c88f80'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which metal is produced industrially by the Hall–Héroult process?', 'Aluminium', 'The Hall–Héroult process is used for industrial production of aluminium from alumina (Al2O3) dissolved in cryolite.', 32),('0d83265e-d8bc-42a2-8a19-39709e55e601'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'Which nonmetal is primarily obtained by fractional distillation of liquid air?', 'Nitrogen', 'Fractional distillation of liquid air separates nitrogen as the major gaseous component due to its lower boiling point compared to oxygen.', 33),('d0b156c1-a760-4c9c-8fea-c9c0aa6337d3'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'multiple_choice', 'In the chlor-alkali process for producing chlorine gas, which species is reduced at the cathode?', 'H2O', 'In brine electrolysis, water is reduced at the cathode to produce hydrogen gas and OH−; Cl− is oxidized at the anode to Cl2.', 34),('0f73adba-3a28-48a3-8e5c-f2ffe8743238'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'true_false', 'Metals tend to gain electrons to form positive ions.', 'False', 'Metals typically lose electrons to form positive ions (cations), whereas nonmetals tend to gain electrons.', 35),('ca3440f9-f588-4197-8144-fe87df19fb5a'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Explain two properties of metals that make them good conductors of electricity.', 'Metals have delocalized electrons that move freely (sea of electrons) and a metallic lattice that allows electron flow, enabling good electrical conductivity.', 'Delocalized electrons move under an electric field, carrying charge; the metallic lattice allows electron mobility even when atoms are fixed in a lattice.', 36),('a67353d3-096c-4fda-88e0-208dae913b29'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'Briefly describe the Hall–Héroult process used to produce aluminum from alumina, including the role of alumina, molten cryolite, and carbon electrodes.', 'Alumina (Al2O3) is dissolved in molten cryolite to lower its melting point; electrolysis with carbon electrodes reduces Al3+ to Al at the cathode while oxygen is produced at the anode and can form CO2 with carbon.', 'Al2O3 is not molten directly due to high melting point; cryolite lowers it; electrolysis yields Al metal at the cathode; O2- reacts at the anode, often with carbon to form CO2.', 37),('1db088f7-3d39-4630-8f6e-c3ffb6af757f'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'An alloy brass contains 70% copper and 30% zinc by mass. If you have 500 g of brass, calculate the masses of copper and zinc in the sample. Show your method and provide final units.', 'Copper: 350 g; Zinc: 150 g', 'Mass of copper = 0.70 × 500 g = 350 g; Mass of zinc = 0.30 × 500 g = 150 g. Final units: grams.', 38),('e62427d5-5f4c-4268-88c5-04c9a201f60c'::uuid, '7eff326d-85a8-4add-8cf4-179b79340483'::uuid, 'fill_blank', 'If 64.9 g of copper(II) oxide (CuO) is reduced to copper metal (Cu) by hydrogen gas according to the equation CuO + H2 → Cu + H2O, what mass of copper is produced (assume 100% yield)? Show all steps and provide final units.', 'Cu produced ≈ 51.9 g', 'Molar masses: CuO 79.545 g/mol; Cu 63.55 g/mol. Moles CuO = 64.9 / 79.545 ≈ 0.817 mol. 1 mol CuO yields 1 mol Cu, so moles Cu = 0.817. Mass Cu = 0.817 × 63.55 ≈ 51.9 g.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
